/**
 * The Army Reduced
 * ----------------
 * Thirty-two thousand men drink at the spring; those who lap like dogs are three hundred, and God reduces the army to them. Stage: a stream at a desert spring, an army kneeling, the water glinting; three hundred hands cupping the water; morning light on a thinning host.
 *
 * Palette 0x101820 → 0x0a0502 · light: water · hero: water
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./gideon-kit.js.
 */

import { THREE, createScene, water, army, well, rock, person } from './gideon-kit.js';

const BG = 0x101820;
const GROUND = 0x0a0502;

export function build(group) {
    const W = createScene(group, { seed: 1859130291, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — water */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-30, 70, -150], 10, 0xfff8e8);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-40, 44, -125, 26], [30, 50, -135, 32], [85, 42, -120, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xf0f4f8, { opacity: 0.75 }), [x, y, z], { s: [s, s * 0.22, s * 0.5] });
    });
    W.backdrop(clouds);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x040201, 0x0c0602);
    W.ground(260, 95, 0, 60, 0x0a0502, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x090402, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x060301), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x060301), [0, -0.05, -14.6]);

    /* army: shields and spears in rank */
    army(W, group, 6.0, 24.7, 8, { shields: [0x0a1015, 0x090502, 0x8a7a2a, 0x3a5a8a] });

    well(W, group, -7.9, 0, -0.8, );

    /* hero: the water — a focal stone in the flow */
    rock(W, group, 0, 0, 11, 1.7, 0x090502);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0x101820, bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: 0.09, s: 1.02 });

    return W.finish();
}

export default { build };
